#include <bits/stdc++.h>
using namespace std;
int main(){ //dp想法如果最長是m個 那一個大的條碼可以被拆成 ([ n ] | [ 1~m ]) 左邊剩餘n個條碼 右邊則帶走1~m個條碼(算一整塊)
	int n,k,m; // dp的i代表當前有幾塊 j則是代表當前的條碼數
	while(cin>>n>>k>>m){ //舉例7 3 4 就是dp[4][7]=dp[3][6]+dp[3][5]+dp[3][4]+dp[3][3]
		map<int,map<int,long long>> dp;
		for(int i=1;i<=m;i++)dp[1][i]=1;
		for(int i=2;i<=k;i++){
			for(int j=1;j<=n;j++){
				for(int l=1;l<=m;l++){
					dp[i][j]+=dp[i-1][j-l];
				}
			}
		}
		cout<<dp[k][n]<<endl;
	}
	return 0;
}

