(function () {
  const totalFrames = 8;
  const keyFrames = [0, 1, 2, 3, 4, 5, 6, 7];
  const stopFrames = [];
  const fastFrames = [];
  const fastonFrames = [];
  const skipFrames = [];
  let currentFrame = 0;
  let track = 0;

  function styles(focus = [], highlight = [], mark = [], bg = []) {
    return [
      { type: 'focus', elements: focus },
      { type: 'highlight', elements: highlight, color: '#ef4444' },
      { type: 'mark', elements: mark, color: '#22c55e' },
      { type: 'background', elements: bg, color: '#dbeafe' }
    ];
  }

  function drawBars(widths, active = -1) {
    const blocks = [];
    widths.forEach((w, i) => {
      for (let t = 0; t < w; t++) blocks.push(i % 2 === 0 ? 1 : 0);
    });
    const bg = [];
    let pos = 0;
    widths.forEach((w, i) => {
      if (i === active) for (let t = 0; t < w; t++) bg.push(pos + t);
      pos += w;
    });
    drawArray('barcode', { type: 'abs', x: 80, y: 0, anchor: 'top-left' }, blocks, styles(bg, bg, [], bg), [0, blocks.length - 1], 'normal', 0, 1, 2, [], [], [], [], [], 4);
    drawText('條碼寬度：' + widths.join(' + ') + ' = ' + widths.reduce((a, b) => a + b, 0), { type: 'rel', ref: 'barcode', anchor: 'raw bottom-left', dx: 0, dy: 34 }, 4);
  }

  function drawDpRow(id, y, label, values, active = -1, source = []) {
    drawText(label, { type: 'abs', x: -40, y, anchor: 'top-left' }, 6);
    drawArray(id, { type: 'abs', x: 95, y, anchor: 'top-left' }, values, styles([active], [active], source, [active]), [0, values.length - 1], 'normal', 0, 1, 4, [], [], [], [], [], 8);
  }

  function renderFrame(f) {
    if (window.setFrameSleep) window.setFrameSleep(0);
    clearAllEditorHighlights();
    if (window.resetMessageCounter) window.resetMessageCounter();
    if (window.resetWordCounter) window.resetWordCounter();
    clearCanvas();

    drawText('Bar Codes：用 DP 計算 BC(n,k,m)', { type: 'abs', x: -70, y: -85, anchor: 'top-left' }, 1);
    drawText('目標範例：n=7, k=4, m=3', { type: 'abs', x: -70, y: -48, anchor: 'top-left' }, 4);

    switch (f) {
      case 0:
        addEditorHighlight(4);
        drawBars([1, 2, 3, 1], 0);
        drawText('BC(7,4,3)：剛好 4 條 bar，總寬度 7，每條最多 3。', { type: 'abs', x: -70, y: 145, anchor: 'top-left' }, 4);
        break;
      case 1:
        addEditorHighlight(6);
        drawBars([1, 2, 3, 1], 2);
        drawText('初始化：只有 1 條 bar 時，寬度 1..m 都各有 1 種。', { type: 'abs', x: -70, y: 145, anchor: 'top-left' }, 6);
        drawDpRow('dp1', 210, 'dp[1][j]', [0, 1, 1, 1, 0, 0, 0, 0], 3, [1,2,3]);
        break;
      case 2:
        addEditorHighlight(10);
        drawText('轉移：最後一條 bar 帶走 l 單位，前面剩 j-l 單位、i-1 條。', { type: 'abs', x: -70, y: 20, anchor: 'top-left' }, 10);
        drawText('dp[i][j] = sum(dp[i-1][j-l]), 1 <= l <= m', { type: 'abs', x: -70, y: 60, anchor: 'top-left' }, 10);
        drawDpRow('dp1', 140, 'dp[1][j]', [0, 1, 1, 1, 0, 0, 0, 0], -1, [1,2,3]);
        drawDpRow('dp2', 215, 'dp[2][j]', [0, 0, 1, 2, 3, 2, 1, 0], 4, [1,2,3]);
        drawArrow({ type: 'rel', ref: 'dp1', index: 1, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp2', index: 4, anchor: 'top', dx: 0, dy: 0 }, { color: '#2563eb', width: '2' }, 10);
        drawArrow({ type: 'rel', ref: 'dp1', index: 2, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp2', index: 4, anchor: 'top', dx: 0, dy: 0 }, { color: '#2563eb', width: '2' }, 10);
        drawArrow({ type: 'rel', ref: 'dp1', index: 3, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp2', index: 4, anchor: 'top', dx: 0, dy: 0 }, { color: '#2563eb', width: '2' }, 10);
        break;
      case 3:
        addEditorHighlight(10);
        drawText('i = 3：累積出使用 3 條 bar 的所有總寬度。', { type: 'abs', x: -70, y: 20, anchor: 'top-left' }, 10);
        drawDpRow('dp1', 110, 'dp[1][j]', [0, 1, 1, 1, 0, 0, 0, 0], -1, []);
        drawDpRow('dp2', 185, 'dp[2][j]', [0, 0, 1, 2, 3, 2, 1, 0], -1, []);
        drawDpRow('dp3', 260, 'dp[3][j]', [0, 0, 0, 1, 3, 6, 7, 6], 7, [4,5,6]);
        drawText('例如 dp[3][7] = dp[2][6]+dp[2][5]+dp[2][4] = 1+2+3 = 6', { type: 'abs', x: -70, y: 340, anchor: 'top-left' }, 10);
        break;
      case 4:
        addEditorHighlight(10);
        drawText('i = 4, j = 7：最後一條可以是 1、2、3 單位。', { type: 'abs', x: -70, y: 20, anchor: 'top-left' }, 10);
        drawDpRow('dp3', 140, 'dp[3][j]', [0, 0, 0, 1, 3, 6, 7, 6], -1, [4,5,6]);
        drawDpRow('dp4', 230, 'dp[4][j]', [0, 0, 0, 0, 1, 4, 10, 16], 7, []);
        drawArrow({ type: 'rel', ref: 'dp3', index: 6, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp4', index: 7, anchor: 'top', dx: 0, dy: 0 }, { color: '#dc2626', width: '2' }, 10);
        drawArrow({ type: 'rel', ref: 'dp3', index: 5, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp4', index: 7, anchor: 'top', dx: 0, dy: 0 }, { color: '#dc2626', width: '2' }, 10);
        drawArrow({ type: 'rel', ref: 'dp3', index: 4, anchor: 'bottom', dx: 0, dy: 0 }, { type: 'rel', ref: 'dp4', index: 7, anchor: 'top', dx: 0, dy: 0 }, { color: '#dc2626', width: '2' }, 10);
        drawText('dp[4][7] = 7 + 6 + 3 = 16', { type: 'abs', x: -70, y: 335, anchor: 'top-left' }, 13);
        break;
      case 5:
        addEditorHighlight(13);
        drawDpRow('dp4', 175, 'dp[4][j]', [0, 0, 0, 0, 1, 4, 10, 16], 7, [7]);
        drawText('輸出答案：BC(7,4,3) 共有 16 種。', { type: 'abs', x: -70, y: 270, anchor: 'top-left' }, 13);
        drawText('Sample 1: 7 4 3  -> 16', { type: 'abs', x: -70, y: 315, anchor: 'top-left' }, 13);
        break;
      case 6:
        addEditorHighlight(10);
        drawText('如果 m = 2，每條最多只能寬 2。', { type: 'abs', x: -70, y: 20, anchor: 'top-left' }, 10);
        drawDpRow('m2dp1', 105, 'dp[1][j]', [0, 1, 1, 0, 0, 0, 0, 0], -1, [1,2]);
        drawDpRow('m2dp2', 175, 'dp[2][j]', [0, 0, 1, 2, 1, 0, 0, 0], -1, []);
        drawDpRow('m2dp3', 245, 'dp[3][j]', [0, 0, 0, 1, 3, 3, 1, 0], -1, []);
        drawDpRow('m2dp4', 315, 'dp[4][j]', [0, 0, 0, 0, 1, 4, 6, 4], 7, [7]);
        drawText('Sample 2: 7 4 2  -> 4', { type: 'abs', x: -70, y: 390, anchor: 'top-left' }, 13);
        break;
      default:
        addEditorHighlight(10);
        drawText('複雜度：狀態 k*n，每格枚舉 l=1..m，所以 O(k*n*m)。', { type: 'abs', x: -70, y: 80, anchor: 'top-left' }, 10);
        drawText('資料範圍 n,k,m <= 50，答案保證放得進 signed 64-bit。', { type: 'abs', x: -70, y: 135, anchor: 'top-left' }, 13);
        drawText('注意：map 在 j-l <= 0 時會回傳 0，剛好符合無效狀態。', { type: 'abs', x: -70, y: 190, anchor: 'top-left' }, 10);
        break;
    }
    window.setAutoCamera(1.05, true, 55, 40);
  }

  function findNextKey(frame) {
    for (const k of keyFrames) if (k > frame) return k;
    return -1;
  }
  function findPrevKey(frame) {
    let ans = -1;
    for (const k of keyFrames) if (k < frame) ans = k;
    return ans;
  }

  window.CodeScript = {
    next() { track = 0; if (currentFrame < totalFrames - 1) { currentFrame++; renderFrame(currentFrame); } },
    prev() { track = 0; if (currentFrame > 0) { currentFrame--; renderFrame(currentFrame); } },
    next_key_frame() { const n = findNextKey(currentFrame); if (n !== -1) { track = 1; currentFrame = n; renderFrame(currentFrame); } },
    prev_key_frame() { const p = findPrevKey(currentFrame); if (p !== -1) { track = 1; currentFrame = p; renderFrame(currentFrame); } },
    reset() { track = 0; currentFrame = 0; renderFrame(0); },
    goto(n) { if (n >= 0 && n < totalFrames) { track = 0; currentFrame = n; renderFrame(n); } else if (n === -1) { track = 0; currentFrame = totalFrames - 1; renderFrame(currentFrame); } },
    get_frame_count() { return totalFrames; },
    get_current_frame_index() { return currentFrame; },
    get_current_line() { return [4,6,10,10,10,13,10,10][currentFrame] || 10; },
    get_key_frames() { return keyFrames; },
    get_stop_frames() { return stopFrames; },
    is_stop_frame() { return stopFrames.includes(currentFrame); },
    is_fast_frame() { return fastFrames.includes(currentFrame); },
    is_faston_frame() { return fastonFrames.includes(currentFrame); },
    is_skip_frame() { return skipFrames.includes(currentFrame); },
    has_next_key() { return findNextKey(currentFrame) !== -1; },
    has_prev_key() { return findPrevKey(currentFrame) !== -1; }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => CodeScript.reset());
  else CodeScript.reset();
})();
